-- Trip Management API :: initial schema
--
-- The DDL below is written in the common subset of PostgreSQL and H2 so that a
-- single migration history can be executed against the production database
-- (PostgreSQL) and the in-memory test database (H2) without divergence.
--
-- Conventions:
--   * identity columns use BIGINT GENERATED BY DEFAULT AS IDENTITY (PG10+ / H2)
--   * timestamps are stored as TIMESTAMP (without time zone) and always hold UTC

CREATE TABLE trips (
    id           BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    trip_number  VARCHAR(50)  NOT NULL,
    source       VARCHAR(120) NOT NULL,
    destination  VARCHAR(120) NOT NULL,
    driver_name  VARCHAR(120),
    status       VARCHAR(20)  NOT NULL DEFAULT 'CREATED',
    version      BIGINT       NOT NULL DEFAULT 0,
    created_at   TIMESTAMP    NOT NULL,
    updated_at   TIMESTAMP    NOT NULL
);

-- Trip number is the caller supplied business key and must be unique.
ALTER TABLE trips ADD CONSTRAINT uk_trips_trip_number UNIQUE (trip_number);

ALTER TABLE trips ADD CONSTRAINT ck_trips_status
    CHECK (status IN ('CREATED', 'ASSIGNED', 'IN_TRANSIT', 'COMPLETED', 'CANCELLED'));

ALTER TABLE trips ADD CONSTRAINT ck_trips_trip_number_not_blank
    CHECK (TRIM(trip_number) <> '');

ALTER TABLE trips ADD CONSTRAINT ck_trips_source_not_blank
    CHECK (TRIM(source) <> '');

ALTER TABLE trips ADD CONSTRAINT ck_trips_destination_not_blank
    CHECK (TRIM(destination) <> '');

-- A trip cannot be assigned, started or completed without a driver.
ALTER TABLE trips ADD CONSTRAINT ck_trips_driver_required
    CHECK (status NOT IN ('ASSIGNED', 'IN_TRANSIT', 'COMPLETED') OR driver_name IS NOT NULL);

-- Listing is always scoped by status and ordered by recency, so the leading
-- column of this index is status and the trailing column sorts the page.
CREATE INDEX idx_trips_status_created_at ON trips (status, created_at DESC);

-- Supports filtering by source/destination on the collection endpoint.
CREATE INDEX idx_trips_source_destination ON trips (source, destination);

-- Supports the default "most recent first" listing without a status filter.
CREATE INDEX idx_trips_created_at ON trips (created_at DESC);


CREATE TABLE trip_status_history (
    id          BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    trip_id     BIGINT       NOT NULL,
    from_status VARCHAR(20),
    to_status   VARCHAR(20)  NOT NULL,
    changed_by  VARCHAR(120),
    changed_at  TIMESTAMP    NOT NULL,
    CONSTRAINT fk_status_history_trip FOREIGN KEY (trip_id) REFERENCES trips (id) ON DELETE CASCADE,
    CONSTRAINT ck_status_history_to_status
        CHECK (to_status IN ('CREATED', 'ASSIGNED', 'IN_TRANSIT', 'COMPLETED', 'CANCELLED'))
);

CREATE INDEX idx_status_history_trip ON trip_status_history (trip_id, changed_at DESC);


-- Idempotency records for POST /trips. The unique key on idempotency_key is the
-- mechanism that collapses concurrent duplicate create requests.
CREATE TABLE idempotency_keys (
    id                   BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    idempotency_key      VARCHAR(128) NOT NULL,
    request_fingerprint  VARCHAR(64)  NOT NULL,
    trip_id              BIGINT,
    created_at           TIMESTAMP    NOT NULL,
    CONSTRAINT uk_idempotency_key UNIQUE (idempotency_key)
);

CREATE INDEX idx_idempotency_keys_created_at ON idempotency_keys (created_at);
